CREATE TABLE IF NOT EXISTS deployment_port_bindings (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_id TEXT NOT NULL DEFAULT '', service_id TEXT NOT NULL DEFAULT '', internal_port INTEGER NOT NULL DEFAULT 0, external_port INTEGER NOT NULL, protocol TEXT NOT NULL, exposure TEXT NOT NULL, status TEXT NOT NULL, health TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(protocol,external_port));
CREATE INDEX IF NOT EXISTS deployment_port_bindings_project_idx ON deployment_port_bindings(project_id);
